/* Offline DOM model only; no real browser/native-dialog/visual acceptance. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
function load(file,marker){const source=fs.readFileSync(path.join(__dirname,file),'utf8'),context={require,__dirname,console,setImmediate,URL,URLSearchParams};vm.createContext(context);vm.runInContext(source.slice(0,source.indexOf(marker))+'\nglobalThis.make=harness;globalThis.flush=tick;',context);return context;}
const base=load('workspace_ui_dom_check.js','const tests=[];');
const composer=load('workspace_composer_dom_check.js',"test('opening composer");
const messages=load('workspace_messages_dom_check.js',"test('received navigation");
const tick=base.flush,capability='bounded-text-exchange-v1',tests=[];const test=(name,fn)=>tests.push([name,fn]);
const pure=x=>JSON.parse(JSON.stringify(x));
async function choose(h,value=capability){const field=h.field('composeCapability');field.value=value;for(const f of field.listeners.change||[])f();await tick();}
function responseHarness(options={}) {
 let h;const incoming={version:2,type:'request',capability,operation:'exchange-text',task:'task-books',context:'c'.repeat(64),sender:'alice',recipient:'bob',payload:{prompt:'Fictional <b>question</b>',max_reply_chars:options.limit||512}};
 const info={owner:'bob',recipient:'alice',context:incoming.context,request_digest:'q'.repeat(64),incoming_request:incoming};
 const preview=(body,r)=>r({...info,envelope:{...incoming,type:'result',sender:'bob',recipient:'alice',reply_to:info.request_digest,payload:body.request.payload},preview_digest:'p'.repeat(64)});
 h=base.make({get:(url,r,defaultGet)=>url.startsWith('/api/response-context')?r(info):url.startsWith('/api/state')?r({phase:'ready',inbox:[],summary:{task_state:'requested'},response_composer:true}):defaultGet(url),post:(body,r)=>options.post?options.post(body,r,preview):body.request.action==='preview_response'?preview(body,r):r({kind:'request',card:{...h.card,owner:'bob'}})});
 h.rows.push({selector:'custom-books',task:'task-books',context:'c'.repeat(64),requester:'alice',responder:'bob',phase:'open'});h.field=id=>h.nodes.findLast(n=>n.id===id);h.compose=async()=>{await tick();await h.view('custom-books/bob/response');};h.preview=async(text='Fictional reply')=>{await h.compose();h.field('responseText').value=text;await h.find('Preview exact response').click();};return h;
}
test('default capability keeps legacy six-field wire shape',async()=>{const h=composer.make();await h.preview();assert.equal(h.posts[0].spec.max_items,3);assert.equal(Object.keys(h.posts[0].spec).length,6);assert(!('capability' in h.posts[0].spec));});
test('text selector emits exact seven-field spec and swaps controls',async()=>{const h=composer.make();await h.compose();await choose(h);assert(h.field('composeCount').hidden);assert(!h.field('composeReplyChars').hidden);h.field('composeReplyChars').value='27';await h.find('Preview exact task').click();assert.equal(h.posts[0].spec.capability,capability);assert.equal(h.posts[0].spec.max_reply_chars,27);assert.equal(Object.keys(h.posts[0].spec).length,7);assert(!('max_items' in h.posts[0].spec));});
test('switching back restores exact legacy shape',async()=>{const h=composer.make();await h.compose();await choose(h);await choose(h,'public-resource-shortlist-v1');await h.find('Preview exact task').click();assert.equal(Object.keys(h.posts[0].spec).length,6);assert.equal(h.posts[0].spec.max_items,3);});
test('empty and oversized text prompts never post previews',async()=>{for(const value of ['', '😀'.repeat(513)]){const h=composer.make();await h.compose();await choose(h);h.field('composeQuery').value=value;await h.find('Preview exact task').click();assert.equal(h.posts.length,0);assert.match(h.ids.error.textContent,/512 Unicode/);}});
test('reply character limit is integral and bounded',async()=>{for(const value of ['','0','513','1.5','NaN']){const h=composer.make();await h.compose();await choose(h);h.field('composeReplyChars').value=value;await h.find('Preview exact task').click();assert.equal(h.posts.length,0);}});
test('512 astral characters survive prompt unchanged',async()=>{const h=composer.make();await h.compose();await choose(h);h.field('composeQuery').value='😀'.repeat(512);await h.find('Preview exact task').click();assert.equal(h.posts[0].spec.query,'😀'.repeat(512));});
test('editing text capability requires fresh preview and fences old confirmation',async()=>{const h=composer.make();await h.compose();await choose(h);await h.find('Preview exact task').click();await h.find('Create this reviewed task').click();const stale=h.ids.dialogConfirm.onclick;await h.ids.dialogCancel.click();await h.find('Edit as a new review').click();assert.equal(h.field('composeCapability').value,capability);await choose(h,'public-resource-shortlist-v1');h.ids.confirmation.value='CREATE TASK';stale();await tick();assert.equal(h.posts.length,1);assert(!h.find('Create this reviewed task'));await h.find('Preview exact task').click();assert(!('capability' in h.posts[1].spec));});
test('detached capability input cannot alter reviewed snapshot',async()=>{const h=composer.make();await h.compose();await choose(h);const old=h.field('composeCapability');await h.find('Preview exact task').click();old.value='public-resource-shortlist-v1';await h.find('Create this reviewed task').click();await h.confirm('CREATE TASK');assert.equal(h.posts[1].spec.capability,capability);});
test('text response exposes only inert bounded field and no item controls',async()=>{const h=responseHarness({limit:12});await h.compose();assert(h.field('responseText'));assert(!h.find('Add result item'));assert(!h.find('Remove last item'));assert.match(h.ids.content.textContent,/at most 12 Unicode/);assert.equal(h.posts.length,0);});
test('empty and oversize responses fail before preview post',async()=>{for(const value of ['', '😀'.repeat(13)]){const h=responseHarness({limit:12});await h.preview(value);assert.equal(h.posts.length,0);assert.match(h.ids.error.textContent,/at most 12 Unicode/);}});
test('maximal Unicode response survives pure preview and unsigned preparation',async()=>{const h=responseHarness();await h.preview('😀'.repeat(512));assert.deepEqual(pure(h.posts[0].request.payload),{text:'😀'.repeat(512)});await h.find('Prepare unsigned response review').click();await h.confirm('REVIEW RESPONSE bob');assert.deepEqual(pure(h.posts[1].request.payload),{text:'😀'.repeat(512)});assert.equal(h.posts[1].request.action,'prepare_response');assert.equal(h.posts.length,2);});
test('response snapshot stays frozen and edit restores text',async()=>{const h=responseHarness();await h.compose();const old=h.field('responseText');old.value='Frozen';await h.find('Preview exact response').click();old.value='Changed';await h.find('Edit response as a new preview').click();assert.equal(h.field('responseText').value,'Frozen');assert(!h.find('Prepare unsigned response review'));});
test('stale text response confirmation cannot cross owner',async()=>{const h=responseHarness();await h.preview();await h.find('Prepare unsigned response review').click();const stale=h.ids.dialogConfirm.onclick;await h.view('custom-books/alice/inbox');h.ids.confirmation.value='REVIEW RESPONSE bob';stale();await tick();assert.equal(h.posts.length,1);});
test('lost text preparation is not repeated',async()=>{const h=responseHarness({post:(b,r,p)=>b.request.action==='preview_response'?p(b,r):Promise.reject(Error('lost'))});await h.preview();const prepare=h.find('Prepare unsigned response review');await prepare.click();await h.confirm('REVIEW RESPONSE bob');await prepare.click();assert.equal(h.posts.length,2);assert(prepare.disabled);assert.match(h.ids.content.textContent,/attempted once/);});
test('late text preview cannot replace later task',async()=>{let release;const h=responseHarness({post:(b,r,p)=>new Promise(resolve=>release=()=>resolve(p(b,r)))});await h.preview();await h.view('garden/alice/inbox');release();await tick();assert(!h.find('Prepare unsigned response review'));assert.equal(h.posts.length,1);});
for(const owner of ['alice','bob'])test('received text '+(owner==='bob'?'request':'result')+' stays literal with exact binding and digest',async()=>{const text='<script>execute()</script> https://example.invalid/inert';const h=messages.make({change:data=>{const e=data.messages[0].envelope;e.capability=capability;e.operation='exchange-text';e.payload=owner==='bob'?{prompt:text,max_reply_chars:37}:{text};}});await h.open(owner);assert(h.ids.content.textContent.includes(text));assert(h.ids.content.textContent.includes('d'.repeat(64)));assert(h.ids.content.textContent.includes('b'.repeat(64)));if(owner==='bob')assert.match(h.ids.content.textContent,/maximum reply characters: 37/);assert(!h.nodes.some(n=>['A','IMG','IFRAME','SCRIPT'].includes(n.tagName)));assert.equal(h.posts.length,0);});
test('cancelled text messages preserve processed history',async()=>{const h=messages.make({state:'cancelled',change:data=>{const e=data.messages[0].envelope;e.capability=capability;e.payload={prompt:'Preserved text',max_reply_chars:5};}});await h.open();assert.match(h.ids.content.textContent,/Preserved text/);assert.match(h.ids.content.textContent,/does not undo prior disclosure/);assert.equal(h.posts.length,0);});
(async()=>{let failed=0;for(const[name,fn]of tests){try{await fn();console.log('PASS '+name);}catch(e){failed++;console.error('FAIL '+name+'\n'+e.stack);}}console.log(`${tests.length-failed}/${tests.length} text exchange DOM-model checks passed (not browser tests).`);if(failed)process.exitCode=1;})();
